using Microsoft.Extensions.Logging;

namespace X3Code.Utils.Configurations;

/// <summary>
/// The log events the configuration loader writes. Generated by the LoggerMessage source
/// generator, so a call costs nothing while the level is switched off.
/// </summary>
/// <remarks>
/// Everything goes through <see cref="ILogger"/>, the abstraction. This library brings no sink and
/// no configuration; where the events end up is entirely the consuming application's decision.
/// </remarks>
internal static partial class ConfigurationLoaderLog
{
    [LoggerMessage(EventId = 3000, Level = LogLevel.Debug,
        Message = "Configuration file [{FileName}] resolved to [{FullPath}] for environment [{Environment}].")]
    internal static partial void PathResolved(ILogger logger, string fileName, string fullPath, string environment);

    [LoggerMessage(EventId = 3001, Level = LogLevel.Debug,
        Message = "Loaded configuration [{ConfigurationType}] from [{FullPath}].")]
    internal static partial void ConfigurationLoaded(ILogger logger, string configurationType, string fullPath);
}
